function getUidsFromCookie() {
    if (document.cookie) {
        let cookieMatch = document.cookie.match(/uids=([^;]*)/);
        if (cookieMatch && cookieMatch.length > 0) {
            let json = JSON.parse(atob(cookieMatch[1]));
            if (json && json.tempUIDs) {
                return json.tempUIDs;
            }
        }
    }
    return null;
}
